  add(11,C,'Functions','Inverse relation for a bijection','f(f^{-1}(y))=y','Which identity expresses the right-inverse property of a bijection?',['f(f^{-1}(y))=y^2','f^{-1}(f(y))=y','f(f^{-1}(y))=f(y)'],'A bijection has both inverse-composition identities.','y lies in the range of f.');
  add(11,C,'Functions','Number of constant functions','n','How many constant functions map a nonempty m-element set into an n-element set?',['m','n^m','mn'],'A constant function is determined by its single common output value.','m≥1; codomain has n elements.','Advanced');
  add(11,C,'Functions','Number of onto functions by inclusion-exclusion','\\sum_{k=0}^{n}(-1)^k\\binom nk(n-k)^m','Which inclusion–exclusion expression counts surjections from an m-element set onto an n-element set?',['\\sum_{k=0}^{n}(-1)^k\\binom nk(n-k)^n','\\sum_{k=0}^{m}(-1)^k\\binom mk(n-k)^m','\\sum_{k=0}^{n}\\binom nk(n-k)^m'],'Subtract functions missing at least one codomain element.','m≥n.','Advanced');
  add(11,Q,'Complex numbers','Conjugate of a quotient','\\overline{\\left(\\dfrac{z_1}{z_2}\\right)}=\\dfrac{\\overline{z_1}}{\\overline{z_2}}','How does complex conjugation act on a quotient?',['\\overline{\\left(\\dfrac{z_1}{z_2}\\right)}=\\dfrac{\\overline{z_2}}{\\overline{z_1}}','\\overline{\\left(\\dfrac{z_1}{z_2}\\right)}=\\dfrac{z_1}{\\overline{z_2}}','\\overline{\\left(\\dfrac{z_1}{z_2}\\right)}=\\dfrac{\\overline{z_1}}{z_2}'],'Conjugation preserves division when the denominator is nonzero.','z₂≠0.');
  add(11,Q,'Complex numbers','Modulus of a product','|z_1z_2|=|z_1||z_2|','Which identity relates the modulus of a product to individual moduli?',['|z_1z_2|=|z_1|+|z_2|','|z_1z_2|=|z_1|^2|z_2|','|z_1z_2|=|z_1-z_2|'],'Moduli multiply under complex multiplication.','For all complex z₁,z₂.');
  add(11,Q,'Complex numbers','Modulus of a quotient','\\left|\\dfrac{z_1}{z_2}\\right|=\\dfrac{|z_1|}{|z_2|}','Which formula gives the modulus of a quotient of complex numbers?',['\\left|\\dfrac{z_1}{z_2}\\right|=\\dfrac{|z_2|}{|z_1|}','\\left|\\dfrac{z_1}{z_2}\\right|=|z_1|-|z_2|','\\left|\\dfrac{z_1}{z_2}\\right|=|z_1||z_2|'],'Use |z₁|=|z₁/z₂||z₂|.','z₂≠0.');
  add(11,Q,'Complex numbers','Conjugate of a polar form','\\overline{r(\\cos\\theta+i\\sin\\theta)}=r(\\cos\\theta-i\\sin\\theta)','What is the conjugate of a complex number in polar form?',['r(\\cos\\theta+i\\sin\\theta)','r(\\cos\\theta-i\\sin\\theta)^{-1}','r(\\cos(-\\theta)-i\\sin(-\\theta))'],'Conjugation reflects the point across the real axis.','r≥0.','Advanced');
  add(11,Q,'Quadratic equations','Sum of squares of roots','\\alpha^2+\\beta^2=(\\alpha+\\beta)^2-2\\alpha\\beta','Which identity expresses the sum of squares of roots using their sum and product?',['\\alpha^2+\\beta^2=(\\alpha+\\beta)^2+2\\alpha\\beta','\\alpha^2+\\beta^2=(\\alpha+\\beta)^2-\\alpha\\beta','\\alpha^2+\\beta^2=2\\alpha\\beta-(\\alpha+\\beta)^2'],'Expand the square of the sum.','α,β are roots of a quadratic.');
  add(11,Q,'Quadratic equations','Product of reciprocal roots','\\dfrac{1}{\\alpha\\beta}=\\dfrac{a}{c}','For roots α,β of ax²+bx+c=0, what is 1/(αβ)?',['\\dfrac{c}{a}','-\\dfrac{a}{c}','\\dfrac{b}{c}'],'Use αβ=c/a and take the reciprocal.','ac≠0.','Advanced');
  add(11,Q,'Quadratic equations','Condition for roots to be reciprocals','a=c','What coefficient condition makes the roots of ax²+bx+c=0 have product 1?',['a=-c','b=c','a=0'],'The product of roots is c/a.','a≠0.','Advanced');
  add(11,P,'Permutations','Permutations with repetition allowed','n^r','How many ordered selections of r positions are possible from n symbols when repetition is allowed?',['\\dfrac{n!}{(n-r)!}','\\binom nr','r^n'],'Each position independently has n choices.','Each of r positions can contain any of n symbols.');
  add(11,P,'Combinations','Combinations with repetition','\\binom{n+r-1}{r}','How many selections of r objects are made from n types when repetition is allowed and order is irrelevant?',['\\binom nr','\\binom{n}{r-1}','\\binom{n+r}{r}'],'Use the stars-and-bars interpretation.','n types, r selections.','Advanced');
  add(11,P,'Distributions','Nonnegative integer solutions','\\binom{n+r-1}{r-1}','How many nonnegative integer solutions does x₁+⋯+x_r=n have?',['\\binom{n-1}{r-1}','\\binom{n+r}{r}','r^n'],'Distribute n identical objects among r labelled boxes.','n≥0,r≥1.','Advanced');
  add(11,P,'Distributions','Positive integer solutions','\\binom{n-1}{r-1}','How many positive integer solutions does x₁+⋯+x_r=n have?',['\\binom{n+r-1}{r-1}','\\binom{n}{r}','r^n'],'Reserve one unit in each variable, then distribute the remainder.','n≥r≥1.','Advanced');
  add(11,P,'Permutations','Circular permutations with a fixed object','(n-1)!','How many circular arrangements of n distinct objects are there when rotations are considered identical?',['n!','\\dfrac{n!}{2}','(n-2)!'],'Fix one object to remove rotational duplication.','Distinct objects.');
  add(11,P,'Permutations','Circular permutations of a necklace','\\dfrac{(n-1)!}{2}','How many arrangements of n distinct beads on a necklace are there if rotations and reflections are identical?',['(n-1)!','\\dfrac{n!}{2}','\\dfrac{(n-2)!}{2}'],'After fixing rotation, identify each arrangement with its reverse.','n>2; distinct beads.','Advanced');
  add(11,P,'Derangements','Derangement recurrence','D_n=(n-1)(D_{n-1}+D_{n-2})','Which recurrence counts derangements of n objects?',['D_n=(n-1)(D_{n-1}-D_{n-2})','D_n=n(D_{n-1}+D_{n-2})','D_n=(n-1)D_{n-1}+D_{n-2}'],'Choose the image of one object and split according to a two-cycle.','D₀=1,D₁=0.','Advanced');
  add(11,B,'Binomial theorem','Binomial theorem for a negative integer exponent','(1+x)^{-n}=\\sum_{r=0}^{\\infty}(-1)^r\\binom{n+r-1}{r}x^r','Which series expands (1+x) to a negative integer power?',['(1+x)^{-n}=\\sum_{r=0}^{\\infty}\\binom{n+r-1}{r}x^r','(1+x)^{-n}=\\sum_{r=0}^{n}(-1)^r\\binom nr x^r','(1+x)^{-n}=\\sum_{r=0}^{\\infty}(-1)^r\\binom nr x^r'],'Use the generalized binomial coefficient for negative integer exponent.','|x|<1; n∈N.','Advanced');
  add(11,B,'Binomial theorem','Sum of squared binomial coefficients','\\sum_{r=0}^{n}\\binom nr^2=\\binom{2n}{n}','What is the sum of squares of the binomial coefficients in row n?',['\\sum_{r=0}^{n}\\binom nr^2=2^n','\\sum_{r=0}^{n}\\binom nr^2=\\binom{2n}{n-1}','\\sum_{r=0}^{n}\\binom nr^2=\\binom{2n}{2}'],'Compare the coefficient of xⁿ in (1+x)ⁿ(1+x)ⁿ.','n is a nonnegative integer.','Advanced');
  add(11,S,'Sequences and Series','Harmonic mean of two positive numbers','H=\\dfrac{2ab}{a+b}','What is the harmonic mean of two positive numbers a and b?',['H=\\dfrac{a+b}{2}','H=\\sqrt{ab}','H=\\dfrac{ab}{a+b}'],'The reciprocal of the harmonic mean is the arithmetic mean of reciprocals.','a,b>0.');
  add(11,S,'Sequences and Series','Harmonic mean as reciprocal of arithmetic mean','\\dfrac1H=\\dfrac12\\left(\\dfrac1a+\\dfrac1b\\right)','Which identity defines the harmonic mean of a and b?',['H=\\dfrac12\\left(\\dfrac1a+\\dfrac1b\\right)','\\dfrac1H=\\dfrac{a+b}{2}','\\dfrac1H=\\dfrac{2}{a+b}'],'Take the arithmetic mean of the reciprocals.','a,b>0.');
  add(11,S,'Sequences and Series','Sum of a geometric progression starting at r zero','\\sum_{k=0}^{n-1}ar^k=a\\dfrac{1-r^n}{1-r}','Which formula sums n terms of a GP beginning with a?',['\\sum_{k=0}^{n-1}ar^k=a\\dfrac{r^n-1}{1-r}','\\sum_{k=0}^{n-1}ar^k=a\\dfrac{1-r^{n+1}}{1-r}','\\sum_{k=0}^{n-1}ar^k=a\\dfrac{1-r}{1-r^n}'],'Apply the finite geometric-series identity.','r≠1.');
  add(11,S,'Sequences and Series','Sum of first n terms of a harmonic progression','\\sum_{k=1}^{n}\\dfrac1{a+(k-1)d}','Which expression represents the sum of the first n terms of the HP whose reciprocals form an AP?',['\\sum_{k=1}^{n}\\dfrac1{a+kd}','\\sum_{k=1}^{n}(a+(k-1)d)','\\dfrac{n}{a+(n-1)d}'],'An HP term is the reciprocal of its corresponding AP term.','a+(k−1)d≠0.');
  add(11,S,'Sequences and Series','Sum of reciprocals of first n natural numbers notation','H_n=\\sum_{k=1}^{n}\\dfrac1k','Which notation defines the nth harmonic number?',['H_n=\\sum_{k=0}^{n}\\dfrac1k','H_n=\\sum_{k=1}^{n}k','H_n=\\prod_{k=1}^{n}\\dfrac1k'],'The harmonic numbers are partial sums of the harmonic series.','n≥1.','Advanced');
  add(11,S,'Sequences and Series','Sum of first n cubes via square of triangular number','\\sum_{k=1}^{n}k^3=\\left(\\dfrac{n(n+1)}2\\right)^2','Which formula gives the sum of the first n cubes?',['\\sum_{k=1}^{n}k^3=\\left(\\dfrac{n(n+1)}2\\right)^3','\\sum_{k=1}^{n}k^3=\\dfrac{n^2(n+1)^2}{6}','\\sum_{k=1}^{n}k^3=\\dfrac{n(n+1)(2n+1)}6'],'The sum of cubes is the square of the nth triangular number.','n∈N.');
  add(11,S,'Sequences and Series','Sum of first n fourth powers','\\sum_{k=1}^{n}k^4=\\dfrac{n(n+1)(2n+1)(3n^2+3n-1)}{30}','Which polynomial gives the sum of the first n fourth powers?',['\\sum_{k=1}^{n}k^4=\\dfrac{n^2(n+1)^2(2n+1)}{30}','\\sum_{k=1}^{n}k^4=\\dfrac{n(n+1)(2n+1)}6','\\sum_{k=1}^{n}k^4=\\dfrac{n(n+1)(3n^2+3n-1)}{30}'],'Use the standard Faulhaber formula for fourth powers.','n∈N.','Advanced');
  add(11,T,'Trigonometric identities','Sine of complementary angles','\\sin\\left(\\dfrac\\pi2-x\\right)=\\cos x','Which cofunction identity converts sine of a complementary angle to cosine?',['\\sin\\left(\\dfrac\\pi2-x\\right)=\\sin x','\\sin\\left(\\dfrac\\pi2-x\\right)=-\\cos x','\\sin\\left(\\dfrac\\pi2-x\\right)=\\tan x'],'Sine and cosine exchange under complementary angles.','x in radians.');
  add(11,T,'Trigonometric identities','Cosine of complementary angles','\\cos\\left(\\dfrac\\pi2-x\\right)=\\sin x','Which identity gives cosine of a complementary angle?',['\\cos\\left(\\dfrac\\pi2-x\\right)=\\cos x','\\cos\\left(\\dfrac\\pi2-x\\right)=-\\sin x','\\cos\\left(\\dfrac\\pi2-x\\right)=\\cot x'],'This is the matching cofunction identity.','x in radians.');
  add(11,T,'Trigonometric identities','Tangent of complementary angles','\\tan\\left(\\dfrac\\pi2-x\\right)=\\cot x','Which relation converts tangent of a complementary angle to cotangent?',['\\tan\\left(\\dfrac\\pi2-x\\right)=\\tan x','\\tan\\left(\\dfrac\\pi2-x\\right)=-\\cot x','\\tan\\left(\\dfrac\\pi2-x\\right)=\\sec x'],'Tangent and cotangent are cofunctions.','Where defined.');
  add(11,T,'Trigonometric identities','Sine of a negative angle','\\sin(-x)=-\\sin x','Which parity identity holds for sine?',['\\sin(-x)=\\sin x','\\sin(-x)=-\\cos x','\\sin(-x)=\\cos x'],'Sine is an odd function.','All real x.');
  add(11,T,'Trigonometric identities','Cosine of a negative angle','\\cos(-x)=\\cos x','Which parity identity holds for cosine?',['\\cos(-x)=-\\cos x','\\cos(-x)=\\sin x','\\cos(-x)=-\\sin x'],'Cosine is an even function.','All real x.');
  add(11,T,'Trigonometric identities','Tangent of a negative angle','\\tan(-x)=-\\tan x','Which parity identity holds for tangent?',['\\tan(-x)=\\tan x','\\tan(-x)=-\\cot x','\\tan(-x)=\\cot x'],'Tangent is odd wherever it is defined.','cos x≠0.');
  add(11,T,'Trigonometric identities','Sine rule in a triangle','\\dfrac{a}{\\sin A}=\\dfrac{b}{\\sin B}=\\dfrac{c}{\\sin C}=2R','Which relation connects sides of a triangle to the circumradius?',['\\dfrac{a}{\\cos A}=\\dfrac{b}{\\cos B}=\\dfrac{c}{\\cos C}=2R','\\dfrac{a}{\\sin A}=\\dfrac{b}{\\sin B}=\\dfrac{c}{\\sin C}=R','a\\sin A=b\\sin B=c\\sin C'],'Each side is twice the circumradius times the sine of its opposite angle.','a,b,c opposite A,B,C.','Advanced');
  add(11,T,'Trigonometric identities','Cosine rule in a triangle','c^2=a^2+b^2-2ab\\cos C','Which cosine-rule expression gives side c opposite angle C?',['c^2=a^2+b^2+2ab\\cos C','c^2=a^2+b^2- ab\\cos C','c^2=a^2-b^2-2ab\\cos C'],'This is the law of cosines.','C is the included angle between sides a and b.','Advanced');
  add(11,T,'Trigonometric identities','Area of a triangle using two sides and included angle','\\Delta=\\dfrac12 ab\\sin C','Which expression gives the area when sides a,b and their included angle C are known?',['\\Delta=ab\\sin C','\\Delta=\\dfrac12 ab\\cos C','\\Delta=\\dfrac12(a+b)\\sin C'],'Use one side as base and the perpendicular height b sin C.','C is included between a and b.','Advanced');
  add(11,T,'Trigonometric identities','Half-angle tangent identity','\\tan\\dfrac{x}{2}=\\dfrac{\\sin x}{1+\\cos x}','Which quotient gives tan(x/2) in terms of sin x and cos x?',['\\tan\\dfrac{x}{2}=\\dfrac{\\sin x}{1-\\cos x}','\\tan\\dfrac{x}{2}=\\dfrac{1+\\cos x}{\\sin x}','\\tan\\dfrac{x}{2}=\\dfrac{1-\\cos x}{\\sin x}'],'Rationalise using the complementary half-angle form.','Where denominators are nonzero.');
  add(11,T,'Trigonometric identities','Double-angle tangent in terms of tan x','\\tan 2x=\\dfrac{2\\tan x}{1-\\tan^2x}','Which expression gives tan 2x in terms of tan x?',['\\tan 2x=\\dfrac{2\\tan x}{1+\\tan^2x}','\\tan 2x=\\dfrac{\\tan x}{1-\\tan^2x}','\\tan 2x=\\dfrac{1-\\tan^2x}{2\\tan x}'],'Apply the tangent addition formula with equal angles.','1−tan²x≠0.');
  add(11,T,'Trigonometric identities','Product-to-sum for cosine times cosine','\\cos A\\cos B=\\dfrac12[\\cos(A+B)+\\cos(A-B)]','Which product-to-sum identity expands cos A cos B?',['\\cos A\\cos B=\\dfrac12[\\cos(A+B)-\\cos(A-B)]','\\cos A\\cos B=\\dfrac12[\\sin(A+B)+\\sin(A-B)]','\\cos A\\cos B=\\cos(A+B)+\\cos(A-B)'],'Add the cosine sum and difference formulas.','A,B real.');
  add(11,T,'Trigonometric identities','Product-to-sum for sine times sine','\\sin A\\sin B=\\dfrac12[\\cos(A-B)-\\cos(A+B)]','Which identity converts sin A sin B into a sum of cosines?',['\\sin A\\sin B=\\dfrac12[\\cos(A+B)-\\cos(A-B)]','\\sin A\\sin B=\\dfrac12[\\sin(A+B)-\\sin(A-B)]','\\sin A\\sin B=\\cos(A-B)-\\cos(A+B)'],'Subtract the cosine sum identity from the cosine difference identity.','A,B real.');
  add(11,T,'Trigonometric identities','Product-to-sum for sine times cosine','\\sin A\\cos B=\\dfrac12[\\sin(A+B)+\\sin(A-B)]','Which expression converts sin A cos B into a sum of sines?',['\\sin A\\cos B=\\dfrac12[\\sin(A+B)-\\sin(A-B)]','\\sin A\\cos B=\\dfrac12[\\cos(A+B)+\\cos(A-B)]','\\sin A\\cos B=\\sin(A+B)+\\sin(A-B)'],'Add the sine sum and difference identities.','A,B real.');
  add(12,D,'Three Dimensional Geometry','Distance of a point from a line in symmetric vector form','\\dfrac{|(\\vec{AP}\\times\\vec d)|}{|\\vec d|}','Which expression gives the perpendicular distance of point P from a line through A with direction vector d?',['\\dfrac{|\\vec{AP}\\cdot\\vec d|}{|\\vec d|}','|\\vec{AP}\\times\\vec d|\,|\\vec d|','\\dfrac{|\\vec{AP}\\times\\vec d|}{|\\vec{AP}|}'],'The cross-product magnitude is base times perpendicular height.','d≠0.','Advanced');
  add(12,D,'Three Dimensional Geometry','Distance between parallel lines in vector form','\\dfrac{|(\\vec{A_2A_1}\\times\\vec d)|}{|\\vec d|}','Which expression gives the distance between two parallel lines with common direction d and points A₁,A₂?',['\\dfrac{|\\vec{A_2A_1}\\cdot\\vec d|}{|\\vec d|}','\\dfrac{|\\vec{A_2A_1}\\times\\vec d|}{|\\vec{A_2A_1}|}','|\\vec{A_2A_1}\\times\\vec d|\,|\\vec d|'],'It is the perpendicular component of the joining vector.','The lines are parallel and d≠0.','Advanced');
  add(12,D,'Three Dimensional Geometry','Distance of a point from a line in coordinates','\\dfrac{|(\\vec r-\\vec a)\\times\\vec b|}{|\\vec b|}','What is the distance from position vector r to the line r=a+λb?',['\\dfrac{|(\\vec r-\\vec a)\\cdot\\vec b|}{|\\vec b|}','\\dfrac{|(\\vec r-\\vec a)\\times\\vec b|}{|\\vec r-\\vec a|}','|(\\vec r-\\vec a)\\times\\vec b|\,|\\vec b|'],'The cross product extracts the perpendicular component.','b≠0.','Advanced');
  add(12,D,'Three Dimensional Geometry','Coplanarity of two lines','(\\vec b_1\\times\\vec b_2)\\cdot(\\vec a_2-\\vec a_1)=0','Which scalar-triple-product condition makes two nonparallel lines coplanar?',['(\\vec b_1\\cdot\\vec b_2)(\\vec a_2-\\vec a_1)=0','(\\vec b_1\\times\\vec b_2)\\times(\\vec a_2-\\vec a_1)=0','(\\vec b_1+\\vec b_2)\\cdot(\\vec a_2-\\vec a_1)=0'],'The direction vectors and joining vector must be coplanar.','For nonparallel lines.','Advanced');
  add(12,V,'Vector Algebra','Scalar projection of a on b','\\dfrac{\\vec a\\cdot\\vec b}{|\\vec b|}','What is the scalar component of vector a along nonzero vector b?',['\\dfrac{\\vec a\\cdot\\vec b}{|\\vec a|}','|\\vec a\\times\\vec b|/|\\vec b|','\\vec a\\cdot\\vec b'],'Divide the dot product by the magnitude of the direction vector.','b≠0.');
  add(12,V,'Vector Algebra','Vector projection of a on b','\\operatorname{proj}_{\\vec b}\\vec a=\\dfrac{\\vec a\\cdot\\vec b}{|\\vec b|^2}\\vec b','Which expression gives the vector projection of a onto b?',['\\operatorname{proj}_{\\vec b}\\vec a=\\dfrac{\\vec a\\cdot\\vec b}{|\\vec a|^2}\\vec a','\\operatorname{proj}_{\\vec b}\\vec a=\\dfrac{|\\vec a\\times\\vec b|}{|\\vec b|^2}\\vec b','\\operatorname{proj}_{\\vec b}\\vec a=\\dfrac{\\vec a\\cdot\\vec b}{|\\vec b|}\\vec b'],'The projected vector is its scalar component times the unit vector along b.','b≠0.');
  add(12,V,'Vector Algebra','Area of parallelogram from vectors','|\\vec a\\times\\vec b|','What is the area of the parallelogram generated by vectors a and b?',['\\vec a\\cdot\\vec b','\\dfrac12|\\vec a\\times\\vec b|','|\\vec a||\\vec b|'],'The cross-product magnitude equals ab sin θ.','a,b are adjacent side vectors.');
  add(12,V,'Vector Algebra','Volume of tetrahedron from three vectors','\\dfrac16|[\\vec a\ \\vec b\ \\vec c]|','Which formula gives the volume of a tetrahedron formed by three coterminal edge vectors?',['\\dfrac13|[\\vec a\ \\vec b\ \\vec c]|','\\dfrac12|[\\vec a\ \\vec b\ \\vec c]|','|[\\vec a\ \\vec b\ \\vec c]|'],'A tetrahedron occupies one-sixth of the corresponding parallelepiped.','a,b,c are the three edge vectors.','Advanced');
  add(12,L,'Limits','Standard limit of (e^x−1)/x','\\lim_{x\\to0}\\dfrac{e^x-1}{x}=1','Which standard limit evaluates (eˣ−1)/x as x tends to zero?',['\\lim_{x\\to0}\\dfrac{e^x-1}{x}=0','\\lim_{x\\to0}\\dfrac{e^x-1}{x}=e','\\lim_{x\\to0}\\dfrac{e^x-1}{x}=\\infty'],'It is the derivative of eˣ at zero.','x in radians is not relevant.');
  add(12,L,'Limits','Standard logarithmic limit','\\lim_{x\\to0}\\dfrac{\\ln(1+x)}x=1','Which standard limit evaluates ln(1+x)/x near zero?',['\\lim_{x\\to0}\\dfrac{\\ln(1+x)}x=0','\\lim_{x\\to0}\\dfrac{\\ln(1+x)}x=-1','\\lim_{x\\to0}\\dfrac{\\ln(1+x)}x=\\infty'],'It is the derivative of ln(1+x) at zero.','x>−1 near zero.');
  add(12,L,'Limits','Standard limit of (a^x−1)/x','\\lim_{x\\to0}\\dfrac{a^x-1}{x}=\\ln a','Which constant is the limit of (aˣ−1)/x as x approaches zero?',['\\lim_{x\\to0}\\dfrac{a^x-1}{x}=a','\\lim_{x\\to0}\\dfrac{a^x-1}{x}=\\dfrac1{\\ln a}','\\lim_{x\\to0}\\dfrac{a^x-1}{x}=0'],'Differentiate aˣ at x=0.','a>0.');
  add(12,L,'Limits','Standard limit involving (1+x) to 1/x','\\lim_{x\\to0}(1+x)^{1/x}=e','Which limit defines e through a variable exponent?',['\\lim_{x\\to0}(1+x)^x=e','\\lim_{x\\to0}(1+x)^{1/x}=1','\\lim_{x\\to0}(1-x)^{1/x}=e'],'Take logarithms and use ln(1+x)/x.','x approaches zero.');
  add(12,L,'Limits','Standard limit of (1−cos x)/x²','\\lim_{x\\to0}\\dfrac{1-\\cos x}{x^2}=\\dfrac12','What is the standard value of (1−cos x)/x² at zero?',['\\lim_{x\\to0}\\dfrac{1-\\cos x}{x^2}=1','\\lim_{x\\to0}\\dfrac{1-\\cos x}{x^2}=\\dfrac14','\\lim_{x\\to0}\\dfrac{1-\\cos x}{x^2}=0'],'Use 1−cos x=2sin²(x/2).','x in radians.');
  add(12,L,'Limits','Standard sine quotient limit','\\lim_{x\\to0}\\dfrac{\\sin ax}{\\sin bx}=\\dfrac ab','Which standard limit compares sin(ax) and sin(bx)?',['\\lim_{x\\to0}\\dfrac{\\sin ax}{\\sin bx}=\\dfrac ba','\\lim_{x\\to0}\\dfrac{\\sin ax}{\\sin bx}=ab','\\lim_{x\\to0}\\dfrac{\\sin ax}{\\sin bx}=1'],'Apply sin t/t→1 to numerator and denominator.','b≠0; x in radians.');
  add(12,L,'Differentiation','Derivative of secant','\\dfrac{d}{dx}(\\sec x)=\\sec x\\tan x','Which derivative corresponds to sec x?',['\\dfrac{d}{dx}(\\sec x)=\\sec^2x','\\dfrac{d}{dx}(\\sec x)=-\\sec x\\tan x','\\dfrac{d}{dx}(\\sec x)=\\sec x\\cot x'],'Differentiate 1/cos x.','cos x≠0.');
  add(12,L,'Differentiation','Derivative of cosecant','\\dfrac{d}{dx}(\\csc x)=-\\csc x\\cot x','Which derivative corresponds to cosec x?',['\\dfrac{d}{dx}(\\csc x)=\\csc x\\cot x','\\dfrac{d}{dx}(\\csc x)=-\\csc^2x','\\dfrac{d}{dx}(\\csc x)=\\csc x\\tan x'],'Differentiate 1/sin x.','sin x≠0.');
  add(12,L,'Differentiation','Derivative of inverse cotangent','\\dfrac{d}{dx}(\\cot^{-1}x)=-\\dfrac1{1+x^2}','Which derivative is used for the principal inverse cotangent?',['\\dfrac{d}{dx}(\\cot^{-1}x)=\\dfrac1{1+x^2}','\\dfrac{d}{dx}(\\cot^{-1}x)=-\\dfrac1{\\sqrt{1-x^2}}','\\dfrac{d}{dx}(\\cot^{-1}x)=\\dfrac1{1-x^2}'],'Differentiate cot y=x implicitly.','Principal branch convention.');
  add(12,L,'Differentiation','Derivative of inverse secant','\\dfrac{d}{dx}(\\sec^{-1}x)=\\dfrac1{|x|\\sqrt{x^2-1}}','Which derivative corresponds to inverse secant?',['\\dfrac{d}{dx}(\\sec^{-1}x)=\\dfrac1{\\sqrt{x^2-1}}','\\dfrac{d}{dx}(\\sec^{-1}x)=-\\dfrac1{|x|\\sqrt{x^2-1}}','\\dfrac{d}{dx}(\\sec^{-1}x)=\\dfrac1{x\\sqrt{1-x^2}}'],'Use implicit differentiation of sec y=x.','|x|>1; principal inverse branch.');
  add(12,L,'Differentiation','Derivative of inverse cosecant','\\dfrac{d}{dx}(\\csc^{-1}x)=-\\dfrac1{|x|\\sqrt{x^2-1}}','Which derivative corresponds to inverse cosecant?',['\\dfrac{d}{dx}(\\csc^{-1}x)=\\dfrac1{|x|\\sqrt{x^2-1}}','\\dfrac{d}{dx}(\\csc^{-1}x)=-\\dfrac1{\\sqrt{x^2-1}}','\\dfrac{d}{dx}(\\csc^{-1}x)=\\dfrac1{x\\sqrt{1-x^2}}'],'Implicitly differentiate csc y=x.','|x|>1; principal inverse branch.');
  add(12,L,'Differentiation','Derivative of tan inverse of u','\\dfrac{d}{dx}\\tan^{-1}u=\\dfrac{u\'}{1+u^2}','Which chain-rule expression differentiates tan⁻¹(u(x))?',['\\dfrac{d}{dx}\\tan^{-1}u=\\dfrac{u\'}{1-u^2}','\\dfrac{d}{dx}\\tan^{-1}u=\\dfrac1{1+u^2}','\\dfrac{d}{dx}\\tan^{-1}u=\\dfrac{u\'}{\\sqrt{1-u^2}}'],'Multiply the inverse-tangent derivative by u′.','u=u(x).');
  add(12,L,'Differentiation','Derivative of square root of a function','\\dfrac{d}{dx}\\sqrt{u}=\\dfrac{u\'}{2\\sqrt u}','Which expression differentiates √u(x)?',['\\dfrac{d}{dx}\\sqrt{u}=\\dfrac{u\'}{\\sqrt u}','\\dfrac{d}{dx}\\sqrt{u}=\\dfrac{1}{2\\sqrt u}','\\dfrac{d}{dx}\\sqrt{u}=2\\sqrt u\,u\''],'Use the power rule with exponent one-half.','u>0.');
  add(12,L,'Applications of derivatives','Differential approximation','f(x+\\Delta x)\\approx f(x)+f\'(x)\\Delta x','Which first-order approximation estimates a small change in f?',['f(x+\\Delta x)\\approx f(x)+f\'\' (x)(\\Delta x)^2','f(x+\\Delta x)\\approx f\'(x)\\Delta x','f(x+\\Delta x)\\approx f(x)+\\dfrac{f\'(x)}{\\Delta x}'],'The tangent-line linearisation gives the first-order change.','Δx is small and f differentiable.');
