  add(12,L,'Applications of derivatives','Critical point condition','f\'(c)=0','What stationary-point condition is tested when finding local extrema in the interior?',['f\'\'(c)=0','f(c)=0','f\'(c)>0'],'An interior differentiable extremum must have zero first derivative.','f differentiable at interior point c.');
  add(12,L,'Applications of derivatives','Concavity test for local minimum','f\'(c)=0,\\quad f\'\'(c)>0','Which second-derivative test indicates a strict local minimum?',['f\'(c)=0,\\quad f\'\'(c)<0','f\'(c)>0,\\quad f\'\'(c)>0','f\'\'(c)=0'],'Positive second derivative at a stationary point means local concavity upward.','f twice differentiable near c.');
