  add(12,I,'Basic integrals','Integral of cosecant squared','\\int\\csc^2x\,dx=-\\cot x+C','Which antiderivative differentiates to cosec²x?',['\\int\\csc^2x\,dx=\\cot x+C','\\int\\csc^2x\,dx=-\\tan x+C','\\int\\csc^2x\,dx=\\csc x+C'],'The derivative of cot x is −cosec²x.','x in an interval of continuity.');
  add(12,I,'Basic integrals','Integral of secant tangent','\\int\\sec x\\tan x\,dx=\\sec x+C','Which integral yields sec x?',['\\int\\sec x\\tan x\,dx=\\tan x+C','\\int\\sec x\\tan x\,dx=-\\sec x+C','\\int\\sec x\\tan x\,dx=\\csc x+C'],'The derivative of sec x is sec x tan x.','x in an interval of continuity.');
